const isCit = liveryCfg.id === 'WHOOSH_CIT' || liveryCfg.consistType === 'HSR_CIT';
const hexBody = '#' + liveryCfg.bodyColor.toString(16).padStart(6,'0');
const hexS1 = '#' + liveryCfg.stripe1.toString(16).padStart(6,'0');
const drawWindowUnit =(wx,wy,ww,wh)=>{
ctx.fillStyle = '#04070e';
ctx.beginPath();
ctx.roundRect(wx - 5,wy - 4,ww + 10,wh + 8,13);
ctx.fill();
ctx.strokeStyle = '#263346';
ctx.lineWidth = 2.0;
ctx.stroke();
ctx.fillStyle = '#05080f';
ctx.beginPath();
ctx.roundRect(wx,wy,ww,wh,10);
ctx.fill();
};
const drawVerticalKomodoCollar =(rx,ry,rw,rh)=>{
const cg = ctx.createLinearGradient(rx,ry,rx,ry + rh);
cg.addColorStop(0.0,'#e01b2d');
cg.addColorStop(0.50,hexS1);
cg.addColorStop(1.0,'#b50f20');
ctx.fillStyle = cg;
ctx.fillRect(rx,ry,rw,rh);
ctx.save();
ctx.beginPath();
ctx.rect(rx,ry,rw,rh);
ctx.clip();
for(let ty = ry;ty < ry + rh;ty += 44){
ctx.fillStyle =((Math.floor((ty - ry)/ 44)% 2)=== 0)
? 'rgba(255, 76, 94, 0.20)'
: 'rgba(116, 8, 20, 0.26)';
ctx.beginPath();
ctx.moveTo(rx,ty);
ctx.lineTo(rx + rw,ty + 22);
ctx.lineTo(rx,ty + 44);
ctx.closePath();
ctx.fill();
}
ctx.restore();
};
