try{(sb.leafNode || sb.gainNode).disconnect();}catch(_e){}
try{sb.gainNode.gain.cancelScheduledValues(now);}catch(_e){}
sb.gainNode.gain.value = 0.0;
sb.gainNode.gain._lastTgt = 0.0;
