this.eddyBrakeOscB.type = 'triangle';
this.eddyBrakeOscB.frequency.value = 480.0;
this.eddyBrakeFilter = this.ctx.createBiquadFilter();
this.eddyBrakeFilter.type = 'bandpass';
this.eddyBrakeFilter.frequency.value = 520.0;
this.eddyBrakeFilter.Q.value = 2.4;
this.eddyBrakeGain = this.ctx.createGain();
this.eddyBrakeGain.gain.value = 0.0;
this.eddyCabSend = this.ctx.createGain();
this.eddyCabSend.gain.value = 0.52;
this.eddyCabSend.connect(this.cabinBus);
this.eddyBrakeOscA.connect(this.eddyBrakeFilter);
this.eddyBrakeOscB.connect(this.eddyBrakeFilter);
this.eddyBrakeFilter.connect(this.eddyBrakeGain);
this._registerSubBus('maglev_eddy_brake',this.eddyBrakeGain,[this.exteriorBus,this.eddyCabSend]);
this.eddyBrakeOscA.start();
this.eddyBrakeOscB.start();
this.rocketJetSrc = this.ctx.createBufferSource();
