this.rocketJetSrc.loop = true;
this.rocketJetFilter = this.ctx.createBiquadFilter();
this.rocketJetFilter.type = 'lowpass';
this.rocketJetFilter.frequency.value = 620.0;
this.rocketJetFilter.Q.value = 1.25;
const crackleSamples = 1024;
const crackleCurve = new Float32Array(crackleSamples);
for(let i = 0;i < crackleSamples;i++){
const x =(i /(crackleSamples - 1))* 2.0 - 1.0;
crackleCurve[i]= x >= 0.0 ? Math.tanh(x * 5.8):(Math.tanh(x * 2.1)* 0.52);
}
this.rocketCrackleDrive = this.ctx.createGain();
this.rocketCrackleDrive.gain.value = 1.0;
this.rocketCrackleShaper = this.ctx.createWaveShaper();
this.rocketCrackleShaper.curve = crackleCurve;
this.rocketCrackleShaper.oversample = 'none';
this.rocketCrackleBand = this.ctx.createBiquadFilter();
this.rocketCrackleBand.type = 'bandpass';
this.rocketCrackleBand.frequency.value = 1380.0;
this.rocketCrackleBand.Q.value = 1.35;
