this.rocketCabSend = this.ctx.createGain();
this.rocketCabSend.gain.value = 0.56;
this.rocketCabSend.connect(this.cabinBus);
this.rocketStructFilter = this.ctx.createBiquadFilter();
this.rocketStructFilter.type = 'lowpass';
this.rocketStructFilter.frequency.value = 420.0;
this.rocketStructGain = this.ctx.createGain();
this.rocketStructGain.gain.value = 0.0;
this.rocketJetSrc.connect(this.rocketJetFilter);
this.rocketJetFilter.connect(this.rocketJetGain);
this._registerSubBus('rocket_jet_plume',this.rocketJetGain,[this.exteriorBus,this.rocketCabSend]);
this.rocketJetFilter.connect(this.rocketStructFilter);
this.rocketStructFilter.connect(this.rocketStructGain);
this._registerSubBus('rocket_struct_bypass',this.rocketStructGain,[this.cabinBus]);
this.rocketJetSrc.connect(this.rocketCrackleDrive);
this.rocketCrackleDrive.connect(this.rocketCrackleShaper);
this.rocketCrackleShaper.connect(this.rocketCrackleBand);
this.rocketCrackleBand.connect(this.rocketCrackleGain);
this._registerSubBus('rocket_shock_crackle',this.rocketCrackleGain,[this.exteriorBus,this.rocketCabSend]);
this.rocketJetSrc.start();
this.rocketSubOsc = this.ctx.createOscillator();
this.rocketSubOsc.type = 'sawtooth';
this.rocketSubOsc.frequency.value = 46.0;
this.rocketSubFilter = this.ctx.createBiquadFilter();
this.rocketSubFilter.type = 'lowpass';
this.rocketSubFilter.frequency.value = 125.0;
this.rocketSubGain = this.ctx.createGain();
this.rocketSubGain.gain.value = 0.0;
this.rocketSubOsc.connect(this.rocketSubFilter);
this.rocketSubFilter.connect(this.rocketSubGain);
this._registerSubBus('rocket_46hz_sub',this.rocketSubGain,[this.cabinBus,this.exteriorBus]);
this.rocketSubOsc.start();
this.rocketPumpOsc = this.ctx.createOscillator();
this.rocketPumpOsc.type = 'sawtooth';
this.rocketPumpOsc.frequency.value = 1180.0;
this.rocketPumpFilter = this.ctx.createBiquadFilter();
