this.rocketHydGain.gain.value = 0.0;
this.rocketHydOsc.connect(this.rocketHydFilter);
this.rocketHydFilter.connect(this.rocketHydGain);
this._registerSubBus('rocket_hydraulics',this.rocketHydGain,[this.exteriorBus,this.cabinBus]);
this.rocketHydOsc.start();
this.rocketChillSrc = this.ctx.createBufferSource();
this.rocketChillSrc.buffer = this.noiseBuffer;
