announceWhooshPA({idText,text,onCaption}){
if(!this.enabled)return;
this._forensic.speech.announcementsTriggered++;
this.init();
this.cancelAnnouncements();
this.playWhooshPAChime();
const paText = String(idText || text || '').trim();
if(!paText)return;
const canSpeak = typeof window !== 'undefined' && 'speechSynthesis' in window && typeof window.SpeechSynthesisUtterance === 'function';
const voices = canSpeak ?(window.speechSynthesis.getVoices()||[]):[];
const startId = setTimeout(()=>{
if(!this.enabled)return;
if(onCaption)onCaption(`[PA WHOOSH] ${paText}`);
if(canSpeak && voices.length > 0){
const utt = new window.SpeechSynthesisUtterance(paText);
utt.lang = 'id-ID';
utt.rate = 1.02;
utt.pitch = 1.06;
utt.volume = 0.76;
const matchVoice = voices.find((v)=> v.lang && v.lang.toLowerCase().startsWith('id'));
if(matchVoice)utt.voice = matchVoice;
const finishPa =()=>{
this.playWhooshSonicJingle();
const clearTimer = setTimeout(()=>{
if(onCaption)onCaption('');
},950);
this._paTimeouts.push(clearTimer);
};
utt.onend = finishPa;
utt.onerror =()=>{
this._forensic.speech.speechErrorsCount++;
finishPa();
};
try{
window.speechSynthesis.speak(utt);
}catch(_e){
this._forensic.speech.speechErrorsCount++;
finishPa();
}
}else{
this._playCeilingSpeakerCadence(3.1);
const endId = setTimeout(()=>{
this.playWhooshSonicJingle();
if(onCaption)onCaption('');
},3650);
this._paTimeouts.push(endId);
}
},960);
this._paTimeouts.push(startId);
}
