playBridgeExpansionJoint(speedMps,doppler = 1.0){
if(!this.initialized || !this.enabled || !this.noiseBuffer)return;
const absV = Math.abs(speedMps);
if(absV < 4.0)return;
const triggerPulse =(delaySec,gainMul,pitchMul)=>{
const t = this.ctx.currentTime + delaySec;
const sub = this.ctx.createOscillator();
sub.type = 'sine';
sub.frequency.setValueAtTime(102 * pitchMul * doppler,t);
sub.frequency.exponentialRampToValueAtTime(54,t + 0.068);
const sg = this.ctx.createGain();
const vNorm = Math.min(1.0,absV / 97.2);
sg.gain.setValueAtTime((0.032 + vNorm * 0.048)* gainMul,t);
sg.gain.exponentialRampToValueAtTime(0.0008,t + 0.075);
sub.connect(sg);
sg.connect(this.cabinBus);
sg.connect(this.exteriorBus);
sub.start(t);
sub.stop(t + 0.08);
const src = this.ctx.createBufferSource();
src.buffer = this.noiseBuffer;
const flt = this.ctx.createBiquadFilter();
flt.type = 'bandpass';
flt.frequency.value =(360 + absV * 2.8)* pitchMul * doppler;
flt.Q.value = 3.6;
const ng = this.ctx.createGain();
ng.gain.setValueAtTime((0.025 + vNorm * 0.045)* gainMul,t);
ng.gain.exponentialRampToValueAtTime(0.0008,t + 0.042);
src.connect(flt);
flt.connect(ng);
ng.connect(this.exteriorBus);
src.start(t);
src.stop(t + 0.048);
};
const axleGap = Math.max(0.024,Math.min(0.24,2.50 / absV));
triggerPulse(0.0,1.0,1.0);
triggerPulse(axleGap,0.86,0.93);
}
