const now = this.ctx.currentTime;
const isOut = direction !== 'IN';
const dur = isOut ? 0.74 : 0.62;
const spdScale = Math.max(0.65,Math.min(1.55,0.58 + Math.abs(speedMps)/ 115.0));
const panSign = sideSign >= 0 ? 1.0 : -1.0;
