glassOsc.frequency.exponentialRampToValueAtTime(isOut ? 1960.0 : 660.0,breachT + 0.14);
const glassGain = this.ctx.createGain();
glassGain.gain.setValueAtTime(0.0005,breachT + 0.02);
glassGain.gain.linearRampToValueAtTime(0.018 * spdScale,breachT + 0.035);
glassGain.gain.exponentialRampToValueAtTime(0.0004,breachT + 0.16);
glassOsc.connect(glassGain);
glassGain.connect(this.masterGain);
glassOsc.start(breachT + 0.02);
glassOsc.stop(breachT + 0.18);
const popOsc = this.ctx.createOscillator();
popOsc.type = 'sine';
popOsc.frequency.setValueAtTime(98.0,breachT);
popOsc.frequency.exponentialRampToValueAtTime(36.0,breachT + 0.22);
const popGain = this.ctx.createGain();
popGain.gain.setValueAtTime(0.0008,breachT);
popGain.gain.linearRampToValueAtTime(0.082 * spdScale,breachT + 0.022);
popGain.gain.exponentialRampToValueAtTime(0.0008,breachT + 0.25);
popOsc.connect(popGain);
popGain.connect(this.masterGain);
popOsc.start(breachT);
popOsc.stop(breachT + 0.27);
