const isTeleportFill = !this.chunks.has(curIdx);
const maxMountPerFrame = isTeleportFill ? 16 :(this.highSpeedStreamBoost ? 3 : 2);
const mountBudgetMs = isTeleportFill ? 24.0 : 2.2;
