createBogie(isMotorBogie = false,outerEndSign = 0,withTrackBrake = false){
const bogie = new THREE.Group();
const frameGeo = isMotorBogie ? this.mergedMotorBogieFrameGeo : this.mergedTrailerBogieFrameGeo;
const wsGeo = isMotorBogie ? this.mergedMotorWheelsetGeo : this.mergedTrailerWheelsetGeo;
const glowGeo = isMotorBogie ? this.mergedMotorBrakeGlowGeo : this.mergedTrailerBrakeGlowGeo;
const frameMesh = new THREE.Mesh(frameGeo,this.bogieVertexMat);
frameMesh.castShadow = true;
let airSpringMesh = null;
if(this.mergedAirSpringBellowGeo){
airSpringMesh = new THREE.Mesh(this.mergedAirSpringBellowGeo,this.bogieVertexMat);
airSpringMesh.position.set(0,0.84,0);
frameMesh.add(airSpringMesh);
}
const axleF = new THREE.Mesh(wsGeo,this.wheelVertexMat);
axleF.position.set(0,0.5642,-1.25);
const glowF = new THREE.Mesh(glowGeo,this.brakeDiscGlowMat);
axleF.add(glowF);
const axleR = new THREE.Mesh(wsGeo,this.wheelVertexMat);
axleR.position.set(0,0.5642,1.25);
if(isMotorBogie){
axleR.rotation.y = Math.PI;
}
const glowR = new THREE.Mesh(glowGeo,this.brakeDiscGlowMat);
axleR.add(glowR);
if(!this._sharedBogieContactAoGeo){
const B = GeometryBatcher;
const aoParts =[];
const underPlate = new THREE.PlaneGeometry(2.15,3.35);
underPlate.rotateX(-Math.PI * 0.5);
aoParts.push(B.bakePart(underPlate,{position:[0,0.012,0],color: 0x020617}));
underPlate.dispose();
for(const wz of[-1.25,1.25]){
for(const wx of[-0.7175,0.7175]){
const nip = new THREE.PlaneGeometry(0.082,0.34);
nip.rotateX(-Math.PI * 0.5);
aoParts.push(B.bakePart(nip,{position:[wx,0.1072,wz],color: 0x000000}));
nip.dispose();
}
}
this._sharedBogieContactAoGeo = B.mergeParts(aoParts);
this._sharedBogieContactAoGeo.userData.sharedGeo = true;
this._sharedBogieContactAoMat = new THREE.MeshBasicMaterial({
vertexColors: true,
transparent: true,
opacity: 0.42,
depthWrite: false,
polygonOffset: true,
polygonOffsetFactor: -1,
polygonOffsetUnits: -2
});
}
const contactAoMesh = new THREE.Mesh(this._sharedBogieContactAoGeo,this._sharedBogieContactAoMat);
bogie.add(contactAoMesh);
if(outerEndSign !== 0 && this.mergedRailGuardGeo){
const guardMesh = new THREE.Mesh(this.mergedRailGuardGeo,this.bogieVertexMat);
if(outerEndSign > 0){
guardMesh.rotation.y = Math.PI;
}
frameMesh.add(guardMesh);
}
let trackBrakeGroup = null;
let trackBrakeGlow = null;
if(withTrackBrake){
if(!this._sharedTrackBrakeShoeGeo){
const B = GeometryBatcher;
const shoeParts =[];
const glowParts =[];
for(const sx of[-0.7175,0.7175]){
const bar = new THREE.BoxGeometry(0.115,0.088,1.48);
shoeParts.push(B.bakePart(bar,{position:[sx,0.156,0.0],color: 0x1e293b}));
bar.dispose();
for(const sz of[-0.48,0.48]){
const cyl = new THREE.CylinderGeometry(0.032,0.028,0.28,8);
shoeParts.push(B.bakePart(cyl,{position:[sx,0.31,sz],color: 0x94a3b8}));
cyl.dispose();
}
const contactGlow = new THREE.BoxGeometry(0.145,0.032,1.54);
glowParts.push(B.bakePart(contactGlow,{position:[sx,0.118,0.0],color: 0xffffff}));
contactGlow.dispose();
}
this._sharedTrackBrakeShoeGeo = B.mergeParts(shoeParts);
this._sharedTrackBrakeShoeGeo.userData.sharedGeo = true;
this._sharedTrackBrakeGlowGeo = B.mergeParts(glowParts);
this._sharedTrackBrakeGlowGeo.userData.sharedGeo = true;
this._sharedTrackShoeGlowMat = new THREE.MeshBasicMaterial({
color: 0xff6b00,
transparent: true,
opacity: 0.0,
blending: THREE.AdditiveBlending,
depthWrite: false
});
}
trackBrakeGroup = new THREE.Group();
trackBrakeGroup.position.y = 0.082;
trackBrakeGroup.visible = false;
const shoeMesh = new THREE.Mesh(this._sharedTrackBrakeShoeGeo,this.bogieVertexMat);
trackBrakeGlow = new THREE.Mesh(this._sharedTrackBrakeGlowGeo,this._sharedTrackShoeGlowMat);
trackBrakeGroup.add(shoeMesh,trackBrakeGlow);
bogie.add(trackBrakeGroup);
}
bogie.add(frameMesh,axleF,axleR);
bogie.userData ={frameMesh,axleF,axleR,airSpringMesh,isMotorBogie,trackBrakeGroup,trackBrakeGlow};
return bogie;
}
