sandGeo.userData.sharedGeo = true;
const sandMat = new THREE.MeshBasicMaterial({color: 0xfde68a,transparent: true,opacity: 0.72});
for(let i = 0;i < 18;i++){
const mesh = new THREE.Mesh(sandGeo,sandMat);
mesh.visible = false;
this.particleGroup.add(mesh);
this.sandPool.push({mesh,life: 0,vel: new THREE.Vector3()});
}
const MAX_SMOKE = 1400;
const quadBase = new THREE.PlaneGeometry(2.0,2.0);
const smokeInstGeo = new THREE.InstancedBufferGeometry();
smokeInstGeo.index = quadBase.index;
smokeInstGeo.setAttribute('position',quadBase.attributes.position);
smokeInstGeo.setAttribute('uv',quadBase.attributes.uv);
smokeInstGeo.instanceCount = MAX_SMOKE;
this._smokePosScaleArr = new Float32Array(MAX_SMOKE * 4);
this._smokeColAlphaArr = new Float32Array(MAX_SMOKE * 4);
this._smokeParamsArr = new Float32Array(MAX_SMOKE * 4);
this._smokePosScaleAttr = new THREE.InstancedBufferAttribute(this._smokePosScaleArr,4);
this._smokeColAlphaAttr = new THREE.InstancedBufferAttribute(this._smokeColAlphaArr,4);
this._smokeParamsAttr = new THREE.InstancedBufferAttribute(this._smokeParamsArr,4);
this._smokePosScaleAttr.setUsage(THREE.DynamicDrawUsage);
this._smokeColAlphaAttr.setUsage(THREE.DynamicDrawUsage);
this._smokeParamsAttr.setUsage(THREE.DynamicDrawUsage);
smokeInstGeo.setAttribute('aPosScale',this._smokePosScaleAttr);
smokeInstGeo.setAttribute('aColorAlpha',this._smokeColAlphaAttr);
smokeInstGeo.setAttribute('aParams',this._smokeParamsAttr);
if(!this._bakedSmokeNoiseTex){
const sz = 128;
const data = new Uint8Array(sz * sz * 4);
const hashP =(ix,iy,seed)=>{
const x =((ix % sz)+ sz)% sz;
const y =((iy % sz)+ sz)% sz;
const h = Math.sin(x * 127.1 + y * 311.7 + seed * 74.7)* 43758.5453;
return h - Math.floor(h);
};
const tileNoise =(u,v,freq,seed)=>{
const px = u * freq;
const py = v * freq;
const ix = Math.floor(px);
const iy = Math.floor(py);
const fx = px - ix;
const fy = py - iy;
const sx = fx * fx *(3.0 - 2.0 * fx);
const sy = fy * fy *(3.0 - 2.0 * fy);
const wrap =(k)=>((k % freq)+ freq)% freq;
const a = hashP(wrap(ix),wrap(iy),seed);
const b = hashP(wrap(ix + 1),wrap(iy),seed);
const c = hashP(wrap(ix),wrap(iy + 1),seed);
const d = hashP(wrap(ix + 1),wrap(iy + 1),seed);
return(a +(b - a)* sx)+((c +(d - c)* sx)-(a +(b - a)* sx))* sy;
};
const sampleBillow =(u,v,seedOff)=>{
let sum = 0.0;
let amp = 0.54;
let freq = 4;
for(let o = 0;o < 4;o++){
const n = tileNoise(u,v,freq,o * 13.7 + seedOff);
const billow = 1.0 - Math.abs(n * 2.0 - 1.0);
sum +=(n * 0.34 + billow * 0.66)* amp;
freq *= 2;
amp *= 0.48;
}
return Math.min(1.0,Math.max(0.0,sum));
};
const fieldA = new Float32Array(sz * sz);
const fieldB = new Float32Array(sz * sz);
for(let y = 0;y < sz;y++){
for(let x = 0;x < sz;x++){
const u = x / sz;
const v = y / sz;
fieldA[y * sz + x]= sampleBillow(u,v,1.0);
fieldB[y * sz + x]= sampleBillow(u + 0.37,v + 0.61,29.3);
}
}
for(let y = 0;y < sz;y++){
const ym =((y - 1)+ sz)% sz;
const yp =(y + 1)% sz;
for(let x = 0;x < sz;x++){
const xm =((x - 1)+ sz)% sz;
const xp =(x + 1)% sz;
const idx = y * sz + x;
const dnx =(fieldA[y * sz + xp]- fieldA[y * sz + xm])* 2.2;
const dny =(fieldA[yp * sz + x]- fieldA[ym * sz + x])* 2.2;
data[idx * 4]= Math.round(fieldA[idx]* 255);
data[idx * 4 + 1]= Math.round(fieldB[idx]* 255);
data[idx * 4 + 2]= Math.round(Math.min(1.0,Math.max(0.0,dnx * 0.5 + 0.5))* 255);
data[idx * 4 + 3]= Math.round(Math.min(1.0,Math.max(0.0,dny * 0.5 + 0.5))* 255);
}
}
const tex = new THREE.DataTexture(data,sz,sz,THREE.RGBAFormat);
tex.wrapS = THREE.RepeatWrapping;
tex.wrapT = THREE.RepeatWrapping;
tex.minFilter = THREE.LinearFilter;
tex.magFilter = THREE.LinearFilter;
tex.needsUpdate = true;
this._bakedSmokeNoiseTex = tex;
}
const smokeMat = new THREE.ShaderMaterial({
transparent: true,
depthWrite: false,
lights: false,
blending: THREE.NormalBlending,
uniforms:{
uSmokeTex:{value: this._bakedSmokeNoiseTex},
uSealActive:{value: 0.0},
uSealIsCab:{value: 0.0},
uSealInvMatrix:{value: new THREE.Matrix4()}
},
vertexShader:[
'uniform float uSealActive;',
'uniform mat4 uSealInvMatrix;',
'attribute vec4 aPosScale;',
'attribute vec4 aColorAlpha;',
'attribute vec4 aParams;',
'varying vec2 vUv;',
'varying vec4 vColAlpha;',
'varying vec3 vMeta;',
'varying vec3 vSealPos;',
'void main() {',
'  float rad = aPosScale.w;',
'  if (rad <= 0.001 || aColorAlpha.w <= 0.002) {',
'    gl_Position = vec4(2.0, 2.0, 2.0, 1.0);',
'    vUv = uv;',
'    vColAlpha = vec4(0.0);',
'    vMeta = vec3(0.0);',
'    vSealPos = vec3(0.0);',
'    return;',
'  }',
'  vec4 mvCenter = modelViewMatrix * vec4(aPosScale.xyz, 1.0);',
'  float maxViewRad = max(0.36, -mvCenter.z * 0.42);',
'  float nearFade = clamp((-mvCenter.z - 0.65) / 1.85, 0.0, 1.0);',
'  float effRad = min(rad, maxViewRad);',
'  vUv = uv;',
'  vColAlpha = vec4(aColorAlpha.rgb, aColorAlpha.w * nearFade);',
'  vMeta = vec3(aParams.x, aParams.z, aParams.w);',
'  float cs = cos(aParams.y);',
'  float sn = sin(aParams.y);',
'  vec2 rotCorner = vec2(position.x * cs - position.y * sn, position.x * sn + position.y * cs);',
'  if (uSealActive > 0.5) {',
'    vec3 camRight = vec3(viewMatrix[0][0], viewMatrix[1][0], viewMatrix[2][0]);',
'    vec3 camUp = vec3(viewMatrix[0][1], viewMatrix[1][1], viewMatrix[2][1]);',
'    vec3 worldPt = (modelMatrix * vec4(aPosScale.xyz, 1.0)).xyz + (camRight * rotCorner.x + camUp * rotCorner.y) * effRad;',
'    vSealPos = (uSealInvMatrix * vec4(worldPt, 1.0)).xyz;',
'  } else {',
'    vSealPos = vec3(999.0);',
'  }',
'  mvCenter.xy += rotCorner * effRad;',
'  gl_Position = projectionMatrix * mvCenter;',
'}'
].join('\n'),
fragmentShader:[
'uniform sampler2D uSmokeTex;',
'uniform float uSealActive;',
'uniform float uSealIsCab;',
'varying vec2 vUv;',
'varying vec4 vColAlpha;',
'varying vec3 vMeta;',
'varying vec3 vSealPos;',
'void main() {',
'  if (vColAlpha.w <= 0.002) discard;',
'  if (uSealActive > 0.5) {',
'    float minSealZ = (uSealIsCab > 0.5) ? -16.8 : -86.0;',
'    if (vSealPos.z > minSealZ && vSealPos.z < 410.0 && vSealPos.y > -0.30 && vSealPos.y < 4.55) {',
'      float sealHalfW = 2.35 + 0.042 * abs(vSealPos.z);',
'      if (abs(vSealPos.x) < sealHalfW) discard;',
'    }',
'  }',
'  vec2 p = vUv * 2.0 - 1.0;',
'  float r2 = dot(p, p);',
'  if (r2 > 1.0) discard;',
'  float r = sqrt(r2);',
'  vec2 uvA = vUv * 0.82 + vec2(vMeta.y * 0.37, vMeta.z * 0.24);',
'  vec2 uvB = vUv * 1.48 - vec2(vMeta.z * 0.31, vMeta.y * 0.53);',
'  vec4 sA = texture2D(uSmokeTex, uvA);',
'  vec4 sB = texture2D(uSmokeTex, uvB);',
'  float n = mix(sA.r, sB.g, 0.44);',
'  float isCryo = step(vMeta.x, -0.05);',
'  float wispNoise = mix((n - 0.53) * 0.50, (n - 0.46) * 0.62, isCryo);',
'  float edgeMask = 1.0 - smoothstep(mix(0.16, 0.08, isCryo), 0.98, r + wispNoise);',
'  float alpha = clamp(edgeMask * vColAlpha.w, 0.0, 0.94);',
'  if (alpha <= 0.003) discard;',
'  vec2 dNorm = (sA.ba * 2.0 - 1.0) + (sB.ba * 2.0 - 1.0) * 0.5;',
'  vec3 puffNorm = normalize(vec3(p.x * 0.72 + dNorm.x * 0.65, p.y * 0.72 + dNorm.y * 0.65, sqrt(max(0.05, 1.0 - r2))));',
'  float sunDiffuse = clamp(dot(puffNorm, vec3(0.42, 0.76, 0.49)) * 0.5 + 0.52, 0.0, 1.0);',
'  float selfShadow = mix(0.52 + 0.54 * sunDiffuse, 0.78 + 0.30 * sunDiffuse, isCryo);',
'  float rimScatter = pow(clamp(r * 1.05, 0.0, 1.0), 2.1) * mix(0.16 + 0.14 * sunDiffuse, 0.28 + 0.20 * sunDiffuse, isCryo);',
'  vec3 baseCloud = vColAlpha.rgb * selfShadow + vec3(rimScatter * 0.94, rimScatter * 0.99, rimScatter * 1.04);',
'  float coreHeat = max(0.0, vMeta.x);',
'  float coreEnv = clamp(coreHeat * (1.0 - r * 0.72) * (0.44 + 0.74 * n), 0.0, 1.48);',
'  vec3 fireCol = mix(vec3(0.46, 0.84, 1.38), vec3(1.10, 1.24, 1.48), clamp(coreEnv * 0.80, 0.0, 1.0));',
'  vec3 cryoCore = mix(baseCloud, vec3(0.96, 0.995, 1.04), clamp(-vMeta.x * (1.0 - r * 0.65) * 0.65, 0.0, 0.75));',
'  vec3 shadedCloud = mix(baseCloud, cryoCore, isCryo);',
'  vec3 finalCol = mix(shadedCloud, fireCol, clamp(coreEnv * 0.72, 0.0, 0.88));',
'  gl_FragColor = vec4(finalCol, alpha);',
'}'
].join('\n')
});
