nGrad.addColorStop(0.58,'rgba(249, 115, 22, 0.52)');
nGrad.addColorStop(0.84,'rgba(251, 191, 36, 0.88)');
nGrad.addColorStop(1.00,'rgba(254, 249, 195, 1.0)');
