updateSeatbackIfeTexture(speedKmh = 0,distanceS = 398,elevMdpl = 28,nextStationShort = 'KARAWANG',clockHm = '07:30'){
if(!this.ifeCtx || !this.ifeTex)return;
const spInt = Math.round(Number(speedKmh)|| 0);
const sKm = Math.max(0,Math.min(142.3,(Number(distanceS)|| 0)/ 1000));
const elInt = Math.round(Number(elevMdpl)|| 28);
const key = `${this.ifeModeIdx}|${Math.floor(spInt / 2)}|${sKm.toFixed(1)}|${elInt}|${nextStationShort}|${clockHm}|${this.cabinClass}`;
if(key === this._lastIfeKey)return;
this._lastIfeKey = key;
const ctx = this.ifeCtx;
ctx.fillStyle = '#040917';
ctx.fillRect(0,0,256,144);
ctx.fillStyle = '#0f172a';
ctx.fillRect(0,0,256,24);
ctx.fillStyle = '#e11d48';
ctx.fillRect(0,0,68,24);
ctx.fillStyle = '#ffffff';
ctx.font = 'bold 11px sans-serif';
ctx.textAlign = 'center';
ctx.fillText('WHOOSH',34,16);
ctx.fillStyle = '#38bdf8';
ctx.font = 'bold 10px monospace';
ctx.textAlign = 'left';
const modeNames =['PETA RUTE 142,3 KM','TELEMETRI 350 KM/H','WISATA PRIANGAN'];
ctx.fillText(modeNames[this.ifeModeIdx]|| modeNames[0],75,15);
ctx.fillStyle = '#94a3b8';
ctx.textAlign = 'right';
ctx.fillText(clockHm,250,15);
if(this.ifeModeIdx === 0){
ctx.strokeStyle = '#1e293b';
ctx.lineWidth = 4;
ctx.beginPath();
ctx.moveTo(24,72);
ctx.lineTo(232,72);
ctx.stroke();
const prog = Math.max(0,Math.min(1,sKm / 142.3));
const tx = 24 + prog * 208;
ctx.strokeStyle = '#e11d48';
ctx.lineWidth = 4;
ctx.beginPath();
ctx.moveTo(24,72);
ctx.lineTo(tx,72);
ctx.stroke();
const nodes =[
{x: 24,lbl: 'HLM'},
{x: 84,lbl: 'KRW'},
{x: 183,lbl: 'PDL'},
{x: 232,lbl: 'TGL'}
];
for(let n = 0;n < nodes.length;n++){
ctx.fillStyle = tx >= nodes[n].x - 2 ? '#34d399' : '#64748b';
ctx.beginPath();
ctx.arc(nodes[n].x,72,4.5,0,Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#cbd5e1';
ctx.font = 'bold 9px monospace';
ctx.textAlign = 'center';
ctx.fillText(nodes[n].lbl,nodes[n].x,90);
}
ctx.fillStyle = '#38bdf8';
ctx.beginPath();
ctx.arc(tx,72,6,0,Math.PI * 2);
ctx.fill();
ctx.fillStyle = '#f8fafc';
ctx.font = 'bold 16px monospace';
ctx.textAlign = 'left';
ctx.fillText(`${spInt} KM/H`,14,48);
ctx.fillStyle = '#fbbf24';
ctx.font = 'bold 11px monospace';
ctx.textAlign = 'right';
ctx.fillText(`➔ ${String(nextStationShort || 'PADALARANG').slice(0, 10)}`,242,47);
ctx.fillStyle = '#0f172a';
ctx.fillRect(10,104,236,30);
ctx.fillStyle = '#6ee7b7';
ctx.font = 'bold 10px monospace';
ctx.textAlign = 'center';
ctx.fillText(`DK ${Math.floor(sKm)}+${String(Math.round((sKm % 1) * 1000)).padStart(3, '0')} • +${elInt} MDPL • 23°C`,128,123);
}else if(this.ifeModeIdx === 1){
ctx.fillStyle = '#ef4444';
ctx.font = '900 34px monospace';
ctx.textAlign = 'center';
ctx.fillText(`${spInt}`,86,74);
ctx.fillStyle = '#94a3b8';
ctx.font = 'bold 10px monospace';
ctx.fillText('KM / JAM',86,90);
ctx.fillStyle = '#38bdf8';
ctx.font = 'bold 18px monospace';
ctx.fillText(`+${elInt}m`,188,62);
ctx.fillStyle = '#34d399';
ctx.font = 'bold 12px monospace';
ctx.fillText(`Wz ${(this.sperlingWz || 1.42).toFixed(2)}`,188,86);
ctx.fillStyle = '#1e293b';
ctx.fillRect(14,106,228,26);
ctx.fillStyle = '#fbbf24';
ctx.font = 'bold 10px monospace';
ctx.fillText(`STASIUN BERIKUT: ${String(nextStationShort || 'PADALARANG')} • KLIK LAYAR [9]`,128,123);
}else{
ctx.fillStyle = '#1e1b4b';
ctx.fillRect(12,32,232,66);
ctx.fillStyle = '#fbbf24';
ctx.font = 'bold 11px sans-serif';
ctx.textAlign = 'left';
ctx.fillText('EXPLORE JAWA BARAT BERSAMA WHOOSH',20,49);
ctx.fillStyle = '#e2e8f0';
ctx.font = '10px sans-serif';
ctx.fillText('• Masjid Raya Al-Jabbar & Summarecon Gedebage',20,66);
ctx.fillText('• Sate Maranggi Purwakarta & Kebun Teh Walini',20,81);
ctx.fillText('• Kereta Feeder Gratis ke Stasiun Bandung Kota',20,94);
ctx.fillStyle = '#064e3b';
ctx.fillRect(12,106,232,26);
ctx.fillStyle = '#6ee7b7';
ctx.font = 'bold 10px monospace';
ctx.textAlign = 'center';
ctx.fillText('PESAN KOPI & CAMILAN NUSANTARA DI KERETA 5 [K]',128,123);
}
this.ifeTex.needsUpdate = true;
}
setCabinClass(cabinClass = 'ECONOMY'){
const valid =['ECONOMY','BUSINESS','FIRST'].includes(cabinClass)? cabinClass : 'ECONOMY';
if(this.cabinClass === valid && this.interiorCoachGroup)return;
this.cabinClass = valid;
if(valid === 'FIRST' || valid === 'BUSINESS'){
this.vipSnackActive = true;
this.vipSnackOpen = true;
this.playerTrayOpen = true;
this.playerTrayAnim = 1.0;
}
this.coachPidNeedsDraw = true;
if(this.coachBodyGroupRef){
const wasVisible = this.interiorCoachGroup ? this.interiorCoachGroup.visible : false;
if(this.interiorCoachGroup){
this.coachBodyGroupRef.remove(this.interiorCoachGroup);
this._disposeGroupNonShared(this.interiorCoachGroup);
}
this.interiorCoachGroup = this.build3DCoachInterior(this.coachCarLen,this.coachCfgRef ||{},this.cabinClass);
this.interiorCoachGroup.visible = wasVisible;
this.coachBodyGroupRef.add(this.interiorCoachGroup);
}
}
cyclePlayerBlind(){
if(this.playerBlindTarget < 0.20)this.playerBlindTarget = 0.44;
else if(this.playerBlindTarget < 0.65)this.playerBlindTarget = 0.84;
else this.playerBlindTarget = 0.06;
return this.playerBlindTarget;
}
