this._cabinGVel += gAcc * stepDt;
this._cabinGSpring = THREE.MathUtils.clamp(this._cabinGSpring + this._cabinGVel * stepDt,-1.60,1.60);
this._cabinLatGSpring +=(rawLatG - this._cabinLatGSpring)* Math.min(1.0,stepDt * 10.0);
