placeOnFrame(obj,frame,dirSign = 1){
obj.position.copy(frame.position);
if(dirSign >= 0){
_right.copy(frame.right).normalize();
_negFwd.copy(frame.tangent).negate().normalize();
}else{
_right.copy(frame.right).negate().normalize();
_negFwd.copy(frame.tangent).normalize();
}
_up.crossVectors(_negFwd,_right).normalize();
_right.crossVectors(_up,_negFwd).normalize();
_basisMat.makeBasis(_right,_up,_negFwd);
obj.quaternion.setFromRotationMatrix(_basisMat);
obj.rotateZ(frame.cantAngle *(dirSign >= 0 ? 1 : -1));
}
