if(this._lastMbzDashKey === key)return;
this._lastMbzDashKey = key;
const ctx = this.mbzDashCtx;
ctx.fillStyle = '#020617';
ctx.fillRect(0,0,256,128);
ctx.fillStyle = '#065f46';
ctx.fillRect(6,6,244,28);
