computePassingAeroExcitation(obsS,obsSpeedMps = 0.0,inTunnel = false,lateralSepM = 5.0){
const tDir = this.travelDir >= 0 ? 1 : -1;
const sRel =(obsS - this.aiTrainS)*(-tDir);
const aiCfg = GAME_PREMISE_CARTRIDGE.liveries[this.currentAiLiveryKey]|| GAME_PREMISE_CARTRIDGE.liveries.WHOOSH;
const aiLen = aiCfg && aiCfg.trainLengthM ? aiCfg.trainLengthM : 208.9;
if(sRel < -36.0 || sRel > aiLen + 36.0){
return{cpForce: 0.0,shearRipple: 0.0,envelope: 0.0,qNorm: 0.0,active: false};
}
const vRel = Math.max(10.0,Math.abs(obsSpeedMps)+(this.aiSpeedMps || 85.0));
const qNorm = Math.min(1.35,Math.pow(vRel / 194.44,2.0))*(inTunnel ? 1.62 : 1.0);
const distAtten = Math.min(1.45,Math.pow(5.0 / Math.max(3.6,Math.abs(lateralSepM)),1.65));
const uNose = sRel / 7.2;
const noseWave =(-uNose * Math.exp(-0.5 * uNose * uNose)* 1.65);
const uTail =(sRel - aiLen)/ 8.0;
const tailWave =(uTail * Math.exp(-0.5 * uTail * uTail)* 1.05);
let gangwayRipple = 0.0;
let bodyShear = 0.0;
if(sRel > -4.0 && sRel < aiLen + 4.0){
const env = Math.sin(THREE.MathUtils.clamp(sRel / aiLen,0.0,1.0)* Math.PI);
gangwayRipple = Math.sin((sRel / 25.0)* Math.PI * 2.0)* 0.24 *(0.45 + 0.55 * env);
bodyShear = 0.35 + 0.65 * env;
}
const cpForce =(noseWave + gangwayRipple + tailWave)* qNorm * distAtten;
const envelope = Math.min(1.5,(Math.abs(noseWave)* 0.45 + bodyShear + Math.abs(tailWave)* 0.45)* qNorm * distAtten);
return{
cpForce,
shearRipple: gangwayRipple * qNorm * distAtten,
envelope,
qNorm: qNorm * distAtten,
active: true
};
}
exportCabinState(){
return{
cabinClass: this.cabinClass || 'ECONOMY',
cabinDimMode: Boolean(this.cabinDimMode),
playerBlindPos: Number.isFinite(this.playerBlindTarget)? this.playerBlindTarget :(this.playerBlindPos || 0.06),
playerTrayOpen: Boolean(this.playerTrayTarget > 0.5 || this.playerTrayOpen),
playerSeatReclined: Boolean(this.playerSeatReclined),
seatRotated180: Boolean(this.seatRotated180),
playerReadingLampOn: Boolean(this.playerReadingLampOn),
playerFootrestOpen: Boolean(this.playerFootrestOpen),
playerCoatHung: this.playerCoatHung !== false,
coinTestStanding: this.coinTestStanding !== false,
ancHeadsetActive: Boolean(this.ancHeadsetActive),
merchSouvenirActive: Boolean(this.merchSouvenirActive),
vipSnackOpen: Boolean(this.vipSnackOpen),
usbChargingActive: this.usbChargingActive !== false,
ifeScreenMode: this.ifeScreenMode || 0,
sunVisorDown: Boolean(this.sunVisorDown),
cabSideShadeDown: Boolean(this.cabSideShadeDown)
};
}
applyCabinState(st){
if(!st || typeof st !== 'object')return;
if(st.cabinClass && st.cabinClass !== this.cabinClass){
this.setCabinClass(st.cabinClass);
}else{
this.ensureCoachInteriorBuilt();
}
if(typeof st.cabinDimMode === 'boolean'){
this.setCabinDimMode(st.cabinDimMode);
}
if(Number.isFinite(st.playerBlindPos)){
this.playerBlindTarget = st.playerBlindPos;
this.playerBlindPos = st.playerBlindPos;
}
if(typeof st.playerTrayOpen === 'boolean'){
this.playerTrayOpen = st.playerTrayOpen;
this.playerTrayTarget = st.playerTrayOpen ? 1.0 : 0.0;
}
if(typeof st.playerSeatReclined === 'boolean'){
this.playerSeatReclined = st.playerSeatReclined;
}
if(typeof st.seatRotated180 === 'boolean'){
this.seatRotated180 = st.seatRotated180;
}
if(typeof st.playerReadingLampOn === 'boolean'){
this.playerReadingLampOn = st.playerReadingLampOn;
if(this.playerReadingSpot)this.playerReadingSpot.intensity = st.playerReadingLampOn ? 1.45 : 0.0;
}
if(typeof st.playerFootrestOpen === 'boolean'){
this.playerFootrestOpen = st.playerFootrestOpen;
}
if(typeof st.playerCoatHung === 'boolean'){
this.playerCoatHung = st.playerCoatHung;
if(this.playerJacketGroup)this.playerJacketGroup.visible = st.playerCoatHung;
}
if(typeof st.coinTestStanding === 'boolean'){
this.coinTestStanding = st.coinTestStanding;
}
if(typeof st.ancHeadsetActive === 'boolean'){
this.ancHeadsetActive = st.ancHeadsetActive;
}
if(typeof st.merchSouvenirActive === 'boolean'){
this.merchSouvenirActive = st.merchSouvenirActive;
}
if(typeof st.vipSnackOpen === 'boolean'){
this.vipSnackOpen = st.vipSnackOpen;
if(st.vipSnackOpen)this.vipSnackActive = true;
}
if(typeof st.usbChargingActive === 'boolean'){
this.usbChargingActive = st.usbChargingActive;
}
if(Number.isFinite(st.ifeScreenMode)){
this.ifeScreenMode = st.ifeScreenMode;
}
if(typeof st.sunVisorDown === 'boolean'){
this.sunVisorDown = st.sunVisorDown;
}
if(typeof st.cabSideShadeDown === 'boolean'){
this.cabSideShadeDown = st.cabSideShadeDown;
}
}
_getHeadlampGlareTexture(){
if(this._hlGlareTex)return this._hlGlareTex;
const size = 128;
const canvas = document.createElement('canvas');
canvas.width = size;
canvas.height = size;
const ctx = canvas.getContext('2d');
const half = size * 0.5;
ctx.clearRect(0,0,size,size);
const gOuter = ctx.createRadialGradient(half,half,0,half,half,half);
gOuter.addColorStop(0.0,'rgba(255, 255, 255, 1.0)');
gOuter.addColorStop(0.14,'rgba(248, 252, 255, 0.92)');
gOuter.addColorStop(0.32,'rgba(215, 236, 255, 0.42)');
gOuter.addColorStop(0.62,'rgba(165, 210, 255, 0.11)');
gOuter.addColorStop(1.0,'rgba(120, 180, 255, 0.0)');
ctx.fillStyle = gOuter;
ctx.fillRect(0,0,size,size);
ctx.save();
ctx.translate(half,half);
ctx.scale(1.0,0.13);
const gStreak = ctx.createRadialGradient(0,0,0,0,0,half * 0.98);
gStreak.addColorStop(0.0,'rgba(255, 255, 255, 0.95)');
gStreak.addColorStop(0.35,'rgba(224, 242, 254, 0.48)');
gStreak.addColorStop(1.0,'rgba(186, 230, 253, 0.0)');
ctx.fillStyle = gStreak;
ctx.beginPath();
ctx.arc(0,0,half * 0.98,0,Math.PI * 2);
ctx.fill();
ctx.restore();
for(const ang of[Math.PI * 0.25,-Math.PI * 0.25]){
ctx.save();
ctx.translate(half,half);
ctx.rotate(ang);
ctx.scale(0.62,0.055);
const gRay = ctx.createRadialGradient(0,0,0,0,0,half);
gRay.addColorStop(0.0,'rgba(255, 255, 255, 0.65)');
gRay.addColorStop(0.45,'rgba(224, 242, 254, 0.20)');
gRay.addColorStop(1.0,'rgba(224, 242, 254, 0.0)');
ctx.fillStyle = gRay;
ctx.beginPath();
ctx.arc(0,0,half,0,Math.PI * 2);
ctx.fill();
ctx.restore();
}
const tex = new THREE.CanvasTexture(canvas);
tex.colorSpace = THREE.SRGBColorSpace;
tex.needsUpdate = true;
this._hlGlareTex = tex;
return tex;
}
