getHalimRealtimeSeconds(){
const wibMs = Date.now()+ 7 * 3600 * 1000;
const d = new Date(wibMs);
return d.getUTCHours()* 3600 + d.getUTCMinutes()* 60 + d.getUTCSeconds()+ d.getUTCMilliseconds()* 0.001;
}
syncToHalimRealtimeWIB(smooth = false){
const halimSecs = this.getHalimRealtimeSeconds();
this.halimRealtimeMode = true;
this.customTimeActive = true;
document.querySelectorAll('.weather-card').forEach((b)=> b.classList.remove('active'));
const liveBtn = document.getElementById('btn-sync-halim-wib');
if(liveBtn)liveBtn.classList.add('active');
if(smooth && this.timeSliderSmooth && this.booted){
this._startSmoothTimeTransition(halimSecs);
}else{
this.timeTransActive = false;
this.clockSeconds = halimSecs;
this.timeSliderTargetSec = halimSecs;
this.applyContinuousAtmosphere(this.clockSeconds,this.customRainPct);
}
}
_startSmoothTimeTransition(targetSec){
const cur =((this.clockSeconds % 86400)+ 86400)% 86400;
const tgt =((targetSec % 86400)+ 86400)% 86400;
const diff =((tgt - cur + 43200)% 86400 + 86400)% 86400 - 43200;
this.timeSliderTargetSec = tgt;
this.customTimeActive = true;
if(Math.abs(diff)< 3.0){
this.timeTransActive = false;
this.clockSeconds = tgt;
this.applyContinuousAtmosphere(this.clockSeconds,this.customRainPct);
return;
}
this.timeTransStartSec = cur;
this.timeTransDiffSec = diff;
this.timeTransElapsed = 0.0;
this.timeTransDuration = 30.0;
this.timeTransActive = true;
this._syncEnvPopoverControls();
}
_syncEnvPopoverControls(){
const mins = Math.floor((((this.clockSeconds % 86400)+ 86400)% 86400)/ 60);
const hh = String(Math.floor(mins / 60)).padStart(2,'0');
const mm = String(mins % 60).padStart(2,'0');
const sTime = document.getElementById('slider-time-wib');
const lTime = document.getElementById('lbl-time-wib');
if(sTime && document.activeElement !== sTime && !this.timeTransActive){
sTime.value = String(mins);
}
if(lTime){
if(this.timeTransActive){
const tgtMins = Math.floor((((this.timeSliderTargetSec % 86400)+ 86400)% 86400)/ 60);
const thh = String(Math.floor(tgtMins / 60)).padStart(2,'0');
const tmm = String(tgtMins % 60).padStart(2,'0');
const remSec = Math.max(1,Math.ceil(this.timeTransDuration - this.timeTransElapsed));
lTime.textContent = `${hh}:${mm} ➔ ${thh}:${tmm} (${remSec}d)`;
}else{
lTime.textContent = this.halimRealtimeMode ? `${hh}:${mm} WIB • LIVE` : `${hh}:${mm} WIB`;
}
}
const liveBtn = document.getElementById('btn-sync-halim-wib');
if(liveBtn)liveBtn.classList.toggle('active',Boolean(this.halimRealtimeMode));
const rainPct = Math.round(this.customRainPct || 0);
const sRain = document.getElementById('slider-weather-rain');
const lRain = document.getElementById('lbl-weather-rain');
if(sRain && document.activeElement !== sRain)sRain.value = String(rainPct);
if(lRain){
const rTag = rainPct < 8 ? 'Tenang' :(rainPct < 35 ? 'Gerimis' :(rainPct < 68 ? 'Hujan Deras' : 'Badai Petir'));
lRain.textContent = `${rTag} (${rainPct}%)`;
}
const windPct = Math.round(this.customWindPct ?? 8);
const sWind = document.getElementById('slider-wind-shear');
const lWind = document.getElementById('lbl-wind-shear');
if(sWind && document.activeElement !== sWind)sWind.value = String(windPct);
if(lWind){
const wTag = windPct < 15 ? 'Tenang' :(windPct < 45 ? 'Sedang' :(windPct < 75 ? 'Shear Kuat' : 'Shear Badai'));
lWind.textContent = `${wTag} (${windPct}%)`;
}
}
