const sec =((daySeconds % 86400)+ 86400)% 86400;
const hr = sec / 3600.0;
const rFrac = THREE.MathUtils.clamp((rainPct || 0)/ 100.0,0.0,1.0);
this.customRainPct = rFrac * 100.0;
this.customTimeActive = true;
