syncMbzSpotterEncounter(forceNewSpot = false){
const tDir = this.travelDir >= 0 ? 1 : -1;
const carDir = tDir *(this.mbzCarRelDir || 1);
const playerOnMbz =(this.distanceS >= 10200 && this.distanceS <= 47100);
if(playerOnMbz && Math.abs(this.speedMps)> 6.0){
const leadOffset = carDir === tDir ?(forceNewSpot ? 18.0 : -45.0):(forceNewSpot ? 255.0 : 210.0);
this.mbzCarS = THREE.MathUtils.clamp(this.distanceS + tDir * leadOffset,10450.0,46850.0);
}else{
const hotspots =[12600,16600,21100,26100,34800,38300];
if(forceNewSpot || this.mbzCarS < 10400 || this.mbzCarS > 46900){
this._mbzSpotIdx =((this._mbzSpotIdx || 0)+ 1)% hotspots.length;
this.mbzCarS = hotspots[this._mbzSpotIdx];
}
if(this.train){
const aiDir = -tDir;
const aiOffset =(carDir === aiDir)? -22.0 : 215.0;
this.train.aiTrainS = THREE.MathUtils.clamp(this.mbzCarS + carDir * aiOffset,10100.0,47300.0);
this.train.aiSpeedMps = 95.5;
this.train.passedPlayer = false;
}
}
this.mbzCarPrevS = this.mbzCarS;
}
_syncTunnelCamButtons(locked){
if(locked === this.tunnelCamLocked)return;
this.tunnelCamLocked = locked;
document.querySelectorAll('.cam-btn').forEach((btn)=>{
const m = parseInt(btn.dataset.cam,10);
const applicableInTunnel =(m === 0 || m === 3 || m === 4 || m === 9);
if(!btn.dataset.origTitle){
btn.dataset.origTitle = btn.getAttribute('title')|| '';
}
if(locked && !applicableInTunnel){
btn.disabled = true;
btn.setAttribute('aria-disabled','true');
btn.setAttribute('title','Tidak tersedia saat kereta berada di dalam terowongan (Gunakan CAB 3D, BOGIE, atau COACH)');
}else{
btn.disabled = false;
btn.removeAttribute('aria-disabled');
btn.setAttribute('title',btn.dataset.origTitle);
}
});
}
updateTunnelCameraAvailability(trainInTunnel,loco = null,dir = 1){
const strictlyInTunnel = Boolean(trainInTunnel);
if(!loco){
this.tunnelCine.active = false;
this.tunnelCine.pulse = 0.0;
this._syncTunnelCamButtons(strictlyInTunnel);
if(strictlyInTunnel && this.cameraMode !== 0 && this.cameraMode !== 3 && this.cameraMode !== 4 && this.cameraMode !== 9){
this.preTunnelCameraMode = this.cameraMode;
this.userOverrodeCamInTunnel = false;
this.setCamera(0,true);
}else if(!strictlyInTunnel){
this.userOverrodeCamInTunnel = false;
}
return;
}
const absSpd = Math.abs(this.speedMps);
const isExtCam =(this.cameraMode !== 0 && this.cameraMode !== 3 && this.cameraMode !== 4 && this.cameraMode !== 9);
const predictLeadM = 16.5 + absSpd * 0.62;
const approachingPortal = isExtCam && absSpd > 3.0 && EndlessWorldMathematics.isTunnelZone(this.distanceS + dir * predictLeadM);
const effectiveLock = strictlyInTunnel || approachingPortal ||(this.tunnelCine.active && this.tunnelCine.direction === 'IN');
this._syncTunnelCamButtons(effectiveLock);
if((strictlyInTunnel || approachingPortal)&& isExtCam){
const savedMode = this.cameraMode;
this.preTunnelCameraMode = savedMode;
this.userOverrodeCamInTunnel = false;
_invLocoQuat.copy(_locoQuat).invert();
this.tunnelCine.startLocalPos.copy(this.camera.position).sub(_locoPos).applyQuaternion(_invLocoQuat);
if(this.tunnelCine.startLocalPos.length()> 54.0){
this.tunnelCine.startLocalPos.setLength(54.0);
this.tunnelCine.startLocalPos.y = Math.max(2.6,this.tunnelCine.startLocalPos.y);
}
this.tunnelCine.startLocalQuat.copy(_invLocoQuat).multiply(this.camera.quaternion);
const sideSign = this.tunnelCine.startLocalPos.x >= -0.05 ? 1.0 : -1.0;
this.cabYaw = 0.0;
this.cabPitch = -0.03;
this.setCamera(0,true);
this.tunnelCine.active = true;
this.tunnelCine.direction = 'IN';
this.tunnelCine.elapsed = 0.0;
this.tunnelCine.duration = 0.60;
this.tunnelCine.fromMode = savedMode;
this.tunnelCine.toMode = 0;
this.tunnelCine.sideSign = sideSign;
this.tunnelCine.u = 1.0;
this.tunnelCine.pulse = 0.0;
if(this.audio){
this.audio.playTunnelCameraWhoosh('IN',absSpd,sideSign);
}
const bannerEl = document.getElementById('pa-broadcast-banner');
const textEl = document.getElementById('pa-broadcast-text');
if(bannerEl && textEl){
const msg = '[MODE TEROWONGAN AKTIF] Kamera masuk ke CAB 3D • Otomatis kembali ke kamera semula saat keluar terowongan.';
textEl.textContent = msg;
bannerEl.classList.remove('hidden');
bannerEl.classList.add('flex');
setTimeout(()=>{
if(textEl.textContent === msg){
bannerEl.classList.add('hidden');
bannerEl.classList.remove('flex');
}
},3000);
}
return;
}
if(!strictlyInTunnel && !approachingPortal){
const bannerEl = document.getElementById('pa-broadcast-banner');
const textEl = document.getElementById('pa-broadcast-text');
if(bannerEl && textEl && textEl.textContent && textEl.textContent.startsWith('[MODE TEROWONGAN AKTIF]')){
bannerEl.classList.add('hidden');
bannerEl.classList.remove('flex');
}
if(
this.preTunnelCameraMode !== null &&
!this.userOverrodeCamInTunnel &&
!this.tunnelCine.active
){
const restoreMode = this.preTunnelCameraMode;
const noseTunDepth = EndlessWorldMathematics.getTunnelDepthMeters(this.distanceS);
const nextCheckDist = Math.max(55.0,absSpd * 1.45);
const anotherTunnelAhead = EndlessWorldMathematics.isTunnelZone(this.distanceS + dir * nextCheckDist);
let targetCamCheckS = this.distanceS;
if(restoreMode === 1){
const oz = Math.cos(this.orbitYaw)* Math.cos(this.orbitPitch)* this.orbitDist;
targetCamCheckS = this.distanceS - dir * Math.max(0.0,oz);
}else if(restoreMode === 6){
targetCamCheckS = this.distanceS - dir * 34.0;
}else if(restoreMode === 5){
targetCamCheckS = this.distanceS - dir * Math.max(0.0,this.walkOffset.z);
}
const targetCamTunDepth = EndlessWorldMathematics.getTunnelDepthMeters(targetCamCheckS);
if(noseTunDepth < -16.5 && targetCamTunDepth < -16.5 && !anotherTunnelAhead){
this.preTunnelCameraMode = null;
this.userOverrodeCamInTunnel = false;
if(restoreMode === 2)this.flyByAnchorS = -999999;
if(restoreMode === 7)this.spotterAnchorS = -999999;
const estSide = restoreMode === 1
?(Math.sin(this.orbitYaw)>= 0 ? 1.0 : -1.0)
:(restoreMode === 2 ? -1.0 : 1.0);
this.setCamera(restoreMode,true);
this.tunnelCine.active = true;
this.tunnelCine.direction = 'OUT';
this.tunnelCine.elapsed = 0.0;
this.tunnelCine.duration = 0.72;
this.tunnelCine.fromMode = 0;
this.tunnelCine.toMode = restoreMode;
this.tunnelCine.sideSign = 0;
this.tunnelCine.u = 0.0;
this.tunnelCine.pulse = 0.0;
if(this.audio){
this.audio.playTunnelCameraWhoosh('OUT',absSpd,estSide);
}
}
}
}
}
