const btnBogieTrailer = document.getElementById('btn-bogie-trailer');
const btnBogieMotor = document.getElementById('btn-bogie-motor');
const btnBogie34 = document.getElementById('btn-bogie-34');
const btnBogieSide = document.getElementById('btn-bogie-side');
const btnBogieUnder = document.getElementById('btn-bogie-under');
const btnBogieLamp = document.getElementById('btn-bogie-lamp');
const setBogiePresetView =(presetKey)=>{
this.bogiePreset = presetKey;
if(presetKey === 'FRONT_34'){
this.bogieYaw = 0.88;
this.bogiePitch = 0.02;
this.bogieDist = 2.85;
}else if(presetKey === 'SIDE'){
this.bogieYaw = Math.PI * 0.5;
this.bogiePitch = 0.02;
this.bogieDist = 2.75;
}else if(presetKey === 'UNDER_DISC'){
this.bogieYaw = 2.12;
this.bogiePitch = -0.09;
this.bogieDist = 1.74;
}
if(btnBogie34)btnBogie34.classList.toggle('active',presetKey === 'FRONT_34');
if(btnBogieSide)btnBogieSide.classList.toggle('active',presetKey === 'SIDE');
if(btnBogieUnder)btnBogieUnder.classList.toggle('active',presetKey === 'UNDER_DISC');
};
if(btnBogieTrailer){
btnBogieTrailer.addEventListener('click',()=>{
this.bogieTargetIdx = 0;
if(this.train)this.train.inspectedBogieIdx = 0;
btnBogieTrailer.classList.add('active');
if(btnBogieMotor)btnBogieMotor.classList.remove('active');
this.updateHUD();
});
}
if(btnBogieMotor){
btnBogieMotor.addEventListener('click',()=>{
this.bogieTargetIdx = 1;
if(this.train)this.train.inspectedBogieIdx = 1;
btnBogieMotor.classList.add('active');
if(btnBogieTrailer)btnBogieTrailer.classList.remove('active');
this.updateHUD();
});
}
if(btnBogie34)btnBogie34.addEventListener('click',()=> setBogiePresetView('FRONT_34'));
if(btnBogieSide)btnBogieSide.addEventListener('click',()=> setBogiePresetView('SIDE'));
if(btnBogieUnder)btnBogieUnder.addEventListener('click',()=> setBogiePresetView('UNDER_DISC'));
if(btnBogieLamp){
btnBogieLamp.addEventListener('click',()=>{
this.bogieLampEnabled = !this.bogieLampEnabled;
if(this.train)this.train.bogieLampEnabled = this.bogieLampEnabled;
btnBogieLamp.classList.toggle('active',this.bogieLampEnabled);
});
}
document.querySelectorAll('.cam-btn').forEach((b)=>{
b.addEventListener('click',()=> this.setCamera(parseInt(b.dataset.cam,10)));
});
const applyStationCamAnglePreset =(angleKey)=>{
this.stationCamAngle = angleKey || 'PLATFORM';
if(this.stationCamAngle === 'PLATFORM'){
this.stationCamYaw = 0.48;
this.stationCamPitch = 0.14;
this.stationCamDist = 36.0;
}else if(this.stationCamAngle === 'FACADE'){
const stCur = GAME_PREMISE_CARTRIDGE.stationsList[this.stationCamIdx || 0];
const isKrw = Boolean(stCur && stCur.id === 'KARAWANG');
this.stationCamYaw =(stCur && stCur.id === 'TEGALLUAR')? 1.18 :(isKrw ? -0.72 : -1.18);
this.stationCamPitch = isKrw ? 0.06 : 0.16;
this.stationCamDist = isKrw ? 34.0 : 64.0;
}else{
this.stationCamYaw = 0.72;
this.stationCamPitch = 0.58;
this.stationCamDist = 115.0;
}
document.querySelectorAll('.st-angle-btn').forEach((ab)=>{
ab.classList.toggle('active',ab.dataset.stAngle === this.stationCamAngle);
});
};
document.querySelectorAll('.st-cam-btn').forEach((sb)=>{
sb.addEventListener('click',()=>{
const idx = Math.max(0,Math.min(3,parseInt(sb.dataset.stCam,10)|| 0));
this.stationCamIdx = idx;
document.querySelectorAll('.st-cam-btn').forEach((x)=>{
x.classList.toggle('active',parseInt(x.dataset.stCam,10)=== idx);
});
if(this.stationCamAngle === 'FACADE'){
applyStationCamAnglePreset('FACADE');
}
});
});
document.querySelectorAll('.st-angle-btn').forEach((ab)=>{
ab.addEventListener('click',()=> applyStationCamAnglePreset(ab.dataset.stAngle || 'PLATFORM'));
});
const toggleConsoleDrawer =(forceCollapsed = null)=>{
this.consoleCollapsed = typeof forceCollapsed === 'boolean' ? forceCollapsed : !this.consoleCollapsed;
const shell = document.getElementById('bottom-console-shell');
const iconC = document.getElementById('icon-toggle-console');
const lblC = document.getElementById('lbl-toggle-console');
if(shell)shell.classList.toggle('console-slid-down',this.consoleCollapsed);
if(iconC){
iconC.className = this.consoleCollapsed
? 'ph-bold ph-caret-up text-xs text-amber-300'
: 'ph-bold ph-caret-down text-xs';
}
if(lblC){
lblC.textContent = this.consoleCollapsed ? 'Tampilkan Konsol' : 'Sembunyikan Konsol';
}
};
this._toggleConsoleDrawer = toggleConsoleDrawer;
const btnToggleConsole = document.getElementById('btn-toggle-console');
if(btnToggleConsole){
btnToggleConsole.addEventListener('click',()=> toggleConsoleDrawer());
}
const btnEnvPop = document.getElementById('btn-env-popover');
const envPopPanel = document.getElementById('env-popover-panel');
const btnMoreMenu = document.getElementById('btn-more-menu');
const morePopPanel = document.getElementById('more-popover-panel');
const closeTopPopovers =(exceptEl = null)=>{
if(envPopPanel && envPopPanel !== exceptEl)envPopPanel.classList.add('hidden');
if(morePopPanel && morePopPanel !== exceptEl){
morePopPanel.classList.add('hidden');
morePopPanel.classList.remove('flex');
}
};
if(btnEnvPop && envPopPanel){
btnEnvPop.addEventListener('click',(ev)=>{
ev.stopPropagation();
const willShow = envPopPanel.classList.contains('hidden');
closeTopPopovers(envPopPanel);
envPopPanel.classList.toggle('hidden',!willShow);
if(willShow)this._syncEnvPopoverControls();
});
envPopPanel.addEventListener('pointerdown',(ev)=> ev.stopPropagation());
envPopPanel.addEventListener('click',(ev)=> ev.stopPropagation());
}
if(btnMoreMenu && morePopPanel){
btnMoreMenu.addEventListener('click',(ev)=>{
ev.stopPropagation();
const willShow = morePopPanel.classList.contains('hidden');
closeTopPopovers(morePopPanel);
morePopPanel.classList.toggle('hidden',!willShow);
morePopPanel.classList.toggle('flex',willShow);
});
morePopPanel.addEventListener('click',()=> closeTopPopovers());
}
window.addEventListener('pointerdown',(ev)=>{
const t = ev.target;
if(t && typeof t.closest === 'function'){
if(t.closest('#env-popover-panel')|| t.closest('#btn-env-popover')|| t.closest('#more-popover-panel')|| t.closest('#btn-more-menu')){
return;
}
}
closeTopPopovers();
},{passive: true});
const chkSmoothTime = document.getElementById('chk-smooth-time');
if(chkSmoothTime){
this.timeSliderSmooth = Boolean(chkSmoothTime.checked);
chkSmoothTime.addEventListener('change',(ev)=>{
this.timeSliderSmooth = Boolean(ev.target.checked);
if(!this.timeSliderSmooth && this.timeTransActive){
this.timeTransActive = false;
this.clockSeconds = this.timeSliderTargetSec;
this.applyContinuousAtmosphere(this.clockSeconds,this.customRainPct);
}
});
}
const setTargetTimeMinutes =(minsVal)=>{
const clampedMins = THREE.MathUtils.clamp(minsVal,0,1439);
const targetSec = clampedMins * 60.0;
this.halimRealtimeMode = false;
document.querySelectorAll('.weather-card').forEach((b)=> b.classList.remove('active'));
if(!this.timeSliderSmooth){
this.timeTransActive = false;
this.timeSliderTargetSec = targetSec;
this.customTimeActive = true;
this.clockSeconds = targetSec;
this.applyContinuousAtmosphere(this.clockSeconds,this.customRainPct);
}else{
this._startSmoothTimeTransition(targetSec);
}
};
const btnSyncHalimWib = document.getElementById('btn-sync-halim-wib');
if(btnSyncHalimWib){
btnSyncHalimWib.addEventListener('click',()=> this.syncToHalimRealtimeWIB(this.timeSliderSmooth));
}
const sTimeWib = document.getElementById('slider-time-wib');
if(sTimeWib){
sTimeWib.addEventListener('input',(ev)=> setTargetTimeMinutes(parseFloat(ev.target.value)|| 0));
}
document.querySelectorAll('.quick-wib-btn').forEach((qb)=>{
qb.addEventListener('click',()=>{
const qMin = parseFloat(qb.dataset.quickWib)|| 450;
if(sTimeWib)sTimeWib.value = String(qMin);
setTargetTimeMinutes(qMin);
});
});
const sRainSlider = document.getElementById('slider-weather-rain');
if(sRainSlider){
sRainSlider.addEventListener('input',(ev)=>{
const rPct = THREE.MathUtils.clamp(parseFloat(ev.target.value)|| 0,0,100);
this.customRainPct = rPct;
this.customWindPct = Math.round(THREE.MathUtils.lerp(8.0,94.0,Math.pow(rPct / 100.0,1.12)));
document.querySelectorAll('.weather-card').forEach((b)=> b.classList.remove('active'));
this.applyContinuousAtmosphere(this.clockSeconds,rPct);
});
}
const sWindSlider = document.getElementById('slider-wind-shear');
if(sWindSlider){
sWindSlider.addEventListener('input',(ev)=>{
this.customWindPct = THREE.MathUtils.clamp(parseFloat(ev.target.value)|| 0,0,100);
this._syncEnvPopoverControls();
});
}
const toggleHud =()=>{
this.hudCollapsed = !this.hudCollapsed;
const dock = document.getElementById('bottom-control-dock');
const camBar = document.getElementById('right-cam-bar');
const btnHud = document.getElementById('btn-toggle-hud');
const icon = document.getElementById('icon-toggle-hud');
if(dock){
dock.classList.toggle('translate-y-44',this.hudCollapsed);
dock.classList.toggle('opacity-0',this.hudCollapsed);
dock.classList.toggle('pointer-events-none',this.hudCollapsed);
}
if(camBar){
camBar.classList.toggle('translate-x-20',this.hudCollapsed);
camBar.classList.toggle('opacity-0',this.hudCollapsed);
}
if(btnHud)btnHud.classList.toggle('active',!this.hudCollapsed);
if(icon){
icon.className = this.hudCollapsed
? 'ph-bold ph-eye-slash text-base text-amber-300'
: 'ph-bold ph-eye text-base text-cyan-300';
}
};
document.getElementById('btn-toggle-hud').addEventListener('click',toggleHud);
document.getElementById('btn-toggle-audio').addEventListener('click',()=>{
this.audio.init();
const enabled = this.audio.toggleMute();
document.getElementById('btn-toggle-audio').classList.toggle('active',enabled);
document.getElementById('icon-audio').className = enabled
? 'ph-fill ph-speaker-high text-base'
: 'ph-fill ph-speaker-slash text-base';
});
